!function(){const e=document.documentElement;if(e.classList.remove("no-js"),e.classList.add("js"),document.body.classList.contains("has-animations")){const e=window.sr=ScrollReveal();e.reveal(".hero-title, .hero-paragraph, .hero-cta",{duration:1e3,distance:"40px",easing:"cubic-bezier(0.5, -0.01, 0, 1.005)",origin:"bottom",interval:150}),e.reveal(".feature, .pricing-table",{duration:600,distance:"40px",easing:"cubic-bezier(0.5, -0.01, 0, 1.005)",interval:100,origin:"bottom",viewFactor:.5}),e.reveal(".feature-extended-image",{duration:600,scale:.9,easing:"cubic-bezier(0.5, -0.01, 0, 1.005)",viewFactor:.5})}}();

// Hero image slider — 3 slides, dots, swipe, autoplay
const hero = document.querySelector('.hero-slider');

window.addEventListener('load', () => {
  if (window.sr) window.sr.sync();
});

if (hero) {
  const slides = [
    { src: 'src/img/Pequabuck-Homepage.png',                                                           alt: 'Pequabuck homepage preview' },
    { src: 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1600&q=80', alt: 'Analytics dashboard preview' },
    { src: 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1600&q=80', alt: 'Web app preview' },
  ];

  // Inject slide images
  slides.forEach((s, i) => {
    const img = document.createElement('img');
    img.src = s.src;
    img.alt = s.alt;
    img.decoding = 'async';
    img.loading = i === 0 ? 'eager' : 'lazy';
    if (i === 0) img.classList.add('is-active');
    hero.appendChild(img);
  });

  // Inject the dot pagination AFTER the slider
  const dots = document.createElement('div');
  dots.className = 'hero-slider__dots';
  dots.setAttribute('role', 'tablist');
  dots.setAttribute('aria-label', 'Hero examples');
  slides.forEach((_, i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'hero-slider__dot' + (i === 0 ? ' is-active' : '');
    b.setAttribute('aria-label', `Show example ${i + 1}`);
    b.dataset.idx = String(i);
    dots.appendChild(b);
  });
  // Append the dots OUTSIDE the slider so they sit below it
  hero.insertAdjacentElement('afterend', dots);

  const imgs = Array.from(hero.querySelectorAll('img'));
  const dotBtns = Array.from(dots.querySelectorAll('button'));
  let idx = 0;
  let timer = null;

  const goTo = (n) => {
    n = ((n % imgs.length) + imgs.length) % imgs.length;
    if (n === idx) return;
    imgs[idx].classList.remove('is-active');
    dotBtns[idx].classList.remove('is-active');
    idx = n;
    imgs[idx].classList.add('is-active');
    dotBtns[idx].classList.add('is-active');
  };

  const startAuto = () => {
    stopAuto();
    timer = setInterval(() => goTo(idx + 1), 4500);
  };
  const stopAuto = () => {
    if (timer) { clearInterval(timer); timer = null; }
  };
  const restartAuto = () => { stopAuto(); startAuto(); };

  // Dot clicks
  dotBtns.forEach((b) => {
    b.addEventListener('click', () => {
      goTo(parseInt(b.dataset.idx, 10));
      restartAuto();
    });
  });

  // Pause autoplay on hover
  hero.addEventListener('mouseenter', stopAuto);
  hero.addEventListener('mouseleave', startAuto);

  // Swipe support
  let touchStartX = null;
  let touchStartY = null;
  const SWIPE_THRESHOLD = 40;
  hero.addEventListener('touchstart', (e) => {
    const t = e.touches[0];
    touchStartX = t.clientX;
    touchStartY = t.clientY;
    stopAuto();
  }, { passive: true });
  hero.addEventListener('touchend', (e) => {
    if (touchStartX == null) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStartX;
    const dy = t.clientY - touchStartY;
    // ignore mostly-vertical drags
    if (Math.abs(dx) > SWIPE_THRESHOLD && Math.abs(dx) > Math.abs(dy)) {
      goTo(idx + (dx < 0 ? 1 : -1));
    }
    touchStartX = touchStartY = null;
    startAuto();
  }, { passive: true });

  startAuto();
}

(() => {
  const header = document.querySelector('.site-header');
  const btn = document.querySelector('.nav-toggle');
  const nav = document.querySelector('#site-nav');
  if (!header || !btn || !nav) return;

  const setOpen = (open) => {
    header.classList.toggle('is-nav-open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  };

  btn.addEventListener('click', () => {
    const open = btn.getAttribute('aria-expanded') === 'true';
    setOpen(!open);
  });

  // Close when a link is clicked
  nav.addEventListener('click', (e) => {
    if (e.target.closest('a')) setOpen(false);
  });

  // Close if you tap outside
  document.addEventListener('click', (e) => {
    const clickedInside = header.contains(e.target);
    if (!clickedInside) setOpen(false);
  });

  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') setOpen(false);
  });
})();
